// Regenerates lib/curated.ts from the JSON files in data/guides.
// Static imports keep the guides inside the serverless bundle on Vercel.
import { readdirSync, writeFileSync } from "node:fs";

const files = readdirSync("data/guides").filter((f) => f.endsWith(".json")).sort();
const ident = (f) => "g_" + f.replace(/\.json$/, "").replace(/[^a-z0-9]/gi, "_");
const lines = [
  "// Generated by scripts/build-index.mjs. Do not edit by hand.",
  'import type { Guide } from "./types";',
  ...files.map((f) => `import ${ident(f)} from "@/data/guides/${f}";`),
  "",
  `export const CURATED: Guide[] = [${files.map((f) => `${ident(f)} as Guide`).join(", ")}];`,
  "",
];
writeFileSync("lib/curated.ts", lines.join("\n"));
console.log(`Indexed ${files.length} guides`);
